export const MAX_CATEGORY_IMAGE_BYTES = 500_000;

export function formatCategoryImageSizeError(fileSize: number): string {
  return `Image too large (${Math.round(fileSize / 1024)} KB). Max ${Math.round(MAX_CATEGORY_IMAGE_BYTES / 1024)} KB for localStorage.`;
}

export function readCategoryImageFile(
  file: File,
  onLoad: (dataUrl: string) => void,
  onError: (message: string) => void,
): void {
  if (file.size > MAX_CATEGORY_IMAGE_BYTES) {
    onError(formatCategoryImageSizeError(file.size));
    return;
  }
  const reader = new FileReader();
  reader.onload = () => {
    const result = reader.result;
    if (typeof result === 'string') onLoad(result);
    else onError('Could not read image file.');
  };
  reader.onerror = () => onError('Could not read image file.');
  reader.readAsDataURL(file);
}

export function isCategoryImagePreview(url: string | undefined): url is string {
  return !!url && (url.startsWith('http') || url.startsWith('data:'));
}

import { useId, useRef } from 'react';
import { readCategoryImageFile } from '../lib/categoryImage';

type CategoryImagePickerProps = {
  idPrefix: string;
  previewUrl: string | null;
  urlValue: string;
  onUrlChange: (value: string) => void;
  onFileSelect: (dataUrl: string) => void;
  onFileError?: (message: string) => void;
  urlInputId?: string;
};

export function CategoryImagePicker({
  idPrefix,
  previewUrl,
  urlValue,
  onUrlChange,
  onFileSelect,
  onFileError,
  urlInputId,
}: CategoryImagePickerProps) {
  const fileInputId = useId();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const resolvedUrlInputId = urlInputId ?? `${idPrefix}-image-url`;

  const handleFileChange = (file: File | undefined) => {
    if (!file) return;
    readCategoryImageFile(file, onFileSelect, (message) => onFileError?.(message));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="category-image-picker">
      <div className="category-image-picker__actions">
        <input
          ref={fileInputRef}
          id={fileInputId}
          type="file"
          accept="image/*"
          className="file-input-hidden"
          aria-label="Choose category image from files"
          onChange={(e) => handleFileChange(e.target.files?.[0])}
        />
        <button
          type="button"
          className="btn btn--secondary"
          onClick={() => fileInputRef.current?.click()}
        >
          Choose from files
        </button>
      </div>

      <label className="form-label" htmlFor={resolvedUrlInputId}>
        Paste URL
      </label>
      <input
        id={resolvedUrlInputId}
        type="url"
        placeholder="https://…"
        value={urlValue}
        onChange={(e) => onUrlChange(e.target.value)}
      />

      {previewUrl && (
        <div className="admin-image-preview">
          <img src={previewUrl} alt="Category image preview" />
        </div>
      )}
    </div>
  );
}

